INSERT INTO `global_settings` (`key`, `value`, `created_at`, `updated_at`) VALUES ('hist_timeline', '[{\"year\":\"2018\",\"tag\":{\"en\":\"Foundation\",\"bn\":\"প্রতিষ্ঠা ও সূচনা\"},\"heading\":{\"en\":\"Grand Opening — Medicare Lab Diagnostic Center Is Born\",\"bn\":\"শুভ সূচনা — মেডিকেয়ার ল্যাব ডায়াগনস্টিক সেন্টারের যাত্রা শুরু\"},\"content\":{\"en\":\"With a vision to redefine community healthcare, Medicare Lab opened its doors in Sitakund in 2018 with a dedicated team of specialist physicians.\",\"bn\":\"সীতাকুণ্ডের সাধারণ মানুষের জন্য উন্নত ও নির্ভরযোগ্য স্বাস্থ্যসেবা নিশ্চিত করার প্রত্যয়ে ২০১৮ সালে অভিজ্ঞ বিশেষজ্ঞ চিকিৎসকদের সমন্বয়ে মেডিকেয়ার ল্যাব প্রতিষ্ঠিত হয়।\"},\"badges\":[{\"en\":\"Modern Diagnostics\",\"bn\":\"আধুনিক ডায়াগনস্টিক\"},{\"en\":\"24\\/7 Emergency Desk\",\"bn\":\"২৪\\/৭ জরুরি সেবা\"},{\"en\":\"Outpatient Care\",\"bn\":\"বহির্বিভাগ সেবা\"}],\"image\":null,\"reversed\":false},{\"year\":\"2020\",\"tag\":{\"en\":\"Diagnostics\",\"bn\":\"উন্নত ডায়াগনস্টিক\"},\"heading\":{\"en\":\"Advanced Diagnostic & Imaging Center\",\"bn\":\"উন্নত ডায়াগনস্টিক ও ইমেজিং সেন্টার সম্প্রসারণ\"},\"content\":{\"en\":\"In 2020, Medicare Lab unveiled an expanded diagnostic wing — bringing digital X-ray, ultrasonography, and a modern pathology laboratory together under one roof.\",\"bn\":\"২০২০ সালে মেডিকেয়ার ল্যাব তার ডায়াগনস্টিক বিভাগ সম্প্রসারণ করে এক ছাদের নিচে ডিজিটাল এক্স-রে, আল্ট্রাসনোগ্রাফি এবং অত্যাধুনিক প্যাথলজি ল্যাব চালু করে।\"},\"badges\":[{\"en\":\"Digital X-Ray\",\"bn\":\"ডিজিটাল এক্স-রে\"},{\"en\":\"Ultrasonography\",\"bn\":\"আল্ট্রাসনোগ্রাফি\"},{\"en\":\"Pathology Lab\",\"bn\":\"প্যাথলজি ল্যাব\"}],\"image\":null,\"reversed\":true},{\"year\":\"2022\",\"tag\":{\"en\":\"Specialized Care\",\"bn\":\"বিশেষজ্ঞ চিকিৎসা সেবা\"},\"heading\":{\"en\":\"Dedicated Consultant Chambers & Cardiac Wing\",\"bn\":\"বিশেষজ্ঞ কনসালট্যান্ট চেম্বার ও ডিজিটাল কার্ডিয়াক সেবা\"},\"content\":{\"en\":\"Specialized multi-departmental consultant chambers and digital ECG facilities opened in 2022, giving the community round-the-clock access to expert specialist care.\",\"bn\":\"২০২২ সালে বিভিন্ন বিভাগের বিশেষজ্ঞ চিকিৎসকদের চেম্বার ও ডিজিটাল ইসিজিসহ কার্ডিয়াক সেবা চালু করা হয়, যা এলাকার রোগীদের সার্বক্ষণিক বিশেষজ্ঞ সেবা প্রদান করে।\"},\"badges\":[{\"en\":\"Specialist Chambers\",\"bn\":\"বিশেষজ্ঞ চেম্বার\"},{\"en\":\"Digital ECG\",\"bn\":\"ডিজিটাল ইসিজি\"},{\"en\":\"24\\/7 Patient Care\",\"bn\":\"২৪\\/৭ রোগী সেবা\"}],\"image\":null,\"reversed\":false},{\"year\":\"2024\",\"tag\":{\"en\":\"Innovation\",\"bn\":\"ডিজিটাল উদ্ভাবন\"},\"heading\":{\"en\":\"Telemedicine & Digital Healthcare Launch\",\"bn\":\"টেলিমেডিসিন ও ডিজিটাল স্বাস্থ্যসেবার শুভ উদ্বোধন\"},\"content\":{\"en\":\"Medicare Lab went digital in 2024 — online appointment booking, digital test report delivery, and smart patient management brought expert care into patients\' homes.\",\"bn\":\"২০২৪ সালে মেডিকেয়ার ল্যাব ডিজিটাল সেবা চালু করে — অনলাইন সিরিয়াল বুকিং, দ্রুত ডিজিটাল রিপোর্ট ডেলিভারি এবং স্মার্ট পেশেন্ট ম্যানেজমেন্ট সেবা রোগীদের ঘরে পৌঁছে দেয়।\"},\"badges\":[{\"en\":\"Online Booking\",\"bn\":\"অনলাইন বুকিং\"},{\"en\":\"Digital Test Reports\",\"bn\":\"ডিজিটাল টেস্ট রিপোর্ট\"},{\"en\":\"E-Prescriptions\",\"bn\":\"ই-প্রেসক্রিপশন\"}],\"image\":null,\"reversed\":true},{\"year\":\"2026\",\"tag\":{\"en\":\"Present & Beyond\",\"bn\":\"বর্তমান ও ভবিষ্যৎ রূপকল্প\"},\"heading\":{\"en\":\"Award-Winning Care & Expansion Vision\",\"bn\":\"অঙ্গীকারবদ্ধ স্বাস্থ্যসেবা ও আধুনিক হাসপাতাল রূপকল্প\"},\"content\":{\"en\":\"Today Medicare Lab stands as Sitakund’s most trusted diagnostic healthcare provider — honoured for clinical excellence and actively expanding toward a modern hospital and nursing college.\",\"bn\":\"বর্তমানে মেডিকেয়ার ল্যাব সীতাকুণ্ডের সর্বাধিক বিশ্বস্ত স্বাস্থ্যসেবা প্রতিষ্ঠান — নিজস্ব জমিতে আধুনিক পূর্ণাঙ্গ হাসপাতাল ও আন্তর্জাতিক মানের নার্সিং কলেজ প্রতিষ্ঠার লক্ষ্যে এগিয়ে চলেছে।\"},\"badges\":[{\"en\":\"Trusted Healthcare\",\"bn\":\"বিশ্বস্ত স্বাস্থ্যসেবা\"},{\"en\":\"50+ Specialists\",\"bn\":\"৫০+ বিশেষজ্ঞ চিকিৎসক\"},{\"en\":\"Nursing College Vision\",\"bn\":\"নার্সিং কলেজ রূপকল্প\"}],\"image\":null,\"reversed\":false}]', NOW(), NOW()) ON DUPLICATE KEY UPDATE `value` = VALUES(`value`), `updated_at` = NOW();